SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
BEGIN TRAN

DECLARE @ExpectedFrameworkId UNIQUEIDENTIFIER = '0fe8a9c0-9ea0-4970-9097-d4f73d45dca7';
DECLARE @CanonicalFrameworkId UNIQUEIDENTIFIER;

IF DB_ID(N'Compliance') IS NULL
BEGIN
    THROW 50020, 'Compliance database not found. Cannot validate canonical NABH framework ID.', 1;
END;

SELECT TOP (1) @CanonicalFrameworkId = cf.Id
FROM [Compliance].[dbo].[ComplianceFrameworks] cf
WHERE LOWER(LTRIM(RTRIM(cf.Name))) = LOWER(N'NABH Full Accreditation (Hospital)')
  AND LOWER(LTRIM(RTRIM(cf.Version))) = LOWER(N'6th Edition');

IF @CanonicalFrameworkId IS NULL
BEGIN
    THROW 50021, 'Canonical NABH Full Accreditation (Hospital) 6th Edition framework not found in Compliance.', 1;
END;

IF @CanonicalFrameworkId <> @ExpectedFrameworkId
BEGIN
    THROW 50022, 'Seed blocked: KnowledgeBase NABH framework ID is not canonical. Run framework-id alignment first.', 1;
END;

IF NOT EXISTS (SELECT 1 FROM dbo.Frameworks WHERE Id = '0fe8a9c0-9ea0-4970-9097-d4f73d45dca7')
